=== 0001_init.sql ===
-- 0001_init — baseline schema for the accounts service
CREATE TABLE users_v2 (
    id         INTEGER PRIMARY KEY,
    username   TEXT NOT NULL UNIQUE,
    email      TEXT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE TABLE orders (
    id           INTEGER PRIMARY KEY,
    user_id      INTEGER NOT NULL REFERENCES users_v2(id),
    amount_cents INTEGER NOT NULL,
    status       TEXT NOT NULL,
    created_at   TEXT NOT NULL
);

INSERT INTO schema_migrations (version, applied_at) VALUES ('0001_init', '2025-09-01T10:00:00Z');

=== 0002_add_user_role.sql ===
-- 0002_add_user_role — every account carries a role used for authorization
ALTER TABLE users_v2 ADD COLUMN role TEXT NOT NULL DEFAULT 'member';

INSERT INTO schema_migrations (version, applied_at) VALUES ('0002_add_user_role', '2025-10-14T09:30:00Z');

=== 0003_add_users_last_login.sql ===
-- 0003_add_users_last_login — record the last successful login per account
ALTER TABLE users_v2 ADD COLUMN last_login TEXT;

INSERT INTO schema_migrations (version, applied_at)
VALUES ('0003_add_users_last_login', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));

=== 0004_create_login_audit.sql ===
-- 0004_create_login_audit — append-only audit trail of authentication events
CREATE TABLE login_audit (
    id         INTEGER PRIMARY KEY,
    user_id    INTEGER NOT NULL REFERENCES users_v2(id),
    event      TEXT NOT NULL,
    ip         TEXT,
    created_at TEXT NOT NULL
);

INSERT INTO schema_migrations (version, applied_at)
VALUES ('0004_create_login_audit', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));

